// Shared helpers for the spec generators (Node >= 20, no dependencies).
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync, copyFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const SPEC_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");

export const sha1 = (s) => createHash("sha1").update(s, "utf8").digest("hex");

/** "GENERATED — do not edit" banner. `style` is the comment syntax of the target file. */
export function header(script, sources, style = "//") {
  const lines = [
    `GENERATED — do not edit. Generated by buddy-budget-mobile-spec/scripts/${script}`,
    `from ${sources.join(" + ")}. Re-run \`node scripts/sync-all.mjs\` in the spec repo instead.`,
  ];
  if (style === "xml") return `<!-- ${lines.join("\n     ")} -->`;
  return lines.map((l) => `${style} ${l}`).join("\n");
}

// BB_SYNC_CHECK=1 (set by `sync-all.mjs --check`): write nothing, exit 1 if any output would change.
const CHECK = process.env.BB_SYNC_CHECK === "1";
const stale = [];
process.on("exit", (code) => {
  if (CHECK && stale.length && code === 0) {
    console.error(`  ${stale.length} generated file(s) are out of date; run scripts/sync-all.mjs`);
    process.exitCode = 1;
  }
});

/** Write a file (creating folders) only if its content changed; returns whether it changed. */
export function writeOut(path, content) {
  const buf = typeof content === "string" ? Buffer.from(content, "utf8") : content;
  const changed = !existsSync(path) || !readFileSync(path).equals(buf);
  const shown = relative(process.cwd(), path) || path;
  if (CHECK) {
    if (changed) stale.push(path);
    console.log(`  ${changed ? "STALE    " : "ok       "} ${shown}`);
    return changed;
  }
  if (changed) {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, buf);
  }
  console.log(`  ${changed ? "wrote    " : "unchanged"} ${shown}`);
  return changed;
}

export function copyOut(src, dest) {
  return writeOut(dest, readFileSync(src));
}

export const readJSON = (p) => JSON.parse(readFileSync(p, "utf8"));

export function requireDir(p, what) {
  const abs = resolve(p);
  if (!existsSync(abs)) {
    console.error(`error: ${what} not found at ${abs}`);
    process.exit(1);
  }
  return abs;
}

export { join, resolve, relative, dirname };

/** Words of an identifier source: "font.size.2xl" → handled by tokenIdent; here split camel/snake text. */
export function camel(words) {
  return words
    .filter(Boolean)
    .map((w, i) => (i === 0 ? w.toLowerCase() : w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()))
    .join("");
}

export const upperFirst = (s) => s.charAt(0).toUpperCase() + s.slice(1);
